import React from 'react';

const PayrollPage = () => {
  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark">
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light dark:border-border-dark flex-shrink-0">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Employee Payroll Management</h1>
      </header>
      <div className="p-8">
        <p className="text-subtext-light">This page is under construction. It will contain tools to manage and process payroll for all staff and faculty.</p>
      </div>
    </div>
  );
};

export default PayrollPage;
